import React, { useContext, useState } from 'react';
import { styled } from '@mui/material/styles';
import Badge from '@mui/material/Badge';
import IconButton from '@mui/material/IconButton';
import Button from '@mui/material/Button';
import MenuIcon from '@mui/icons-material/Menu';
import NotificationsIcon from '@mui/icons-material/Notifications';
import ShoppingBagIcon from '@mui/icons-material/ShoppingBag';


import Dialog from '@mui/material/Dialog';
import AppBar from '@mui/material/AppBar';
import Toolbar from '@mui/material/Toolbar';
import Typography from '@mui/material/Typography';
import CloseIcon from '@mui/icons-material/Close';

import { AiOutlineMenuFold, AiOutlineMenuUnfold } from "react-icons/ai";
import {
  Avatar,
  ListItemIcon,
  Menu,
  MenuItem,
} from '@mui/material';
import {
  AccountBoxOutlined,
  Logout,
} from '@mui/icons-material';
import { useNavigate, Link } from 'react-router-dom';
import { MyContext } from '../../App';


const StyledBadge = styled(Badge)(({ theme }) => ({
  '& .MuiBadge-badge': {
    right: -3,
    top: 13,
    border: `2px solid ${theme.palette.background.paper}`,
    padding: '0 4px',
  },
}));

function Header() {
  const context = useContext(MyContext);
  const history = useNavigate();
  const [anchorEl, setAnchorEl] = useState(null);
  const open = Boolean(anchorEl);

  const handleClick = (event) => {
    setAnchorEl(event.currentTarget);
  };
  const handleClose = () => {
    setAnchorEl(null);
  };

 



  

  return (
 <>
    <header className={`w-full h-[auto] py-2 pl-5 pr-7 shadow-md bg-[#fff] border-b border-[rgba(0,0,0,0.1)] flex items-center justify-between`}>
      <div className="part1">
        <Button
          className="!w-[40px] !h-[40px] !rounded-full !min-w-[40px] text-[rgba(0,0,0,0.8)]"
       
        >
        
             <AiOutlineMenuFold className='!text-[#000] !font-[700]' />
            <AiOutlineMenuUnfold className='!text-[#000] !font-[700]' />
          <MenuIcon fontSize="small" />
        </Button>
      </div>

      <div className="w-[40%] flex items-center justify-end gap-3">
        <IconButton aria-label="notifications">
          <StyledBadge badgeContent={3} color="secondary">
            <NotificationsIcon />
          </StyledBadge>
        </IconButton>

        <IconButton aria-label="shopping cart">
          <StyledBadge badgeContent={2} color="primary">
            <ShoppingBagIcon />
          </StyledBadge>
        </IconButton>

       
            <IconButton
              onClick={handleClick}
              aria-controls={open ? 'account-menu' : undefined}
              aria-haspopup="true"
              aria-expanded={open ? 'true' : undefined}
            >
              <StyledBadge color="primary">
                <Avatar sx={{ width: 32, height: 32 }} />
              </StyledBadge>
            </IconButton>

            <Menu
              anchorEl={anchorEl}
              id="account-menu"
              open={open}
              onClose={handleClose}
              onClick={handleClose}
              PaperProps={{
                elevation: 0,
                sx: {
                  overflow: 'visible',
                  filter: 'drop-shadow(0px 2px 8px rgba(0,0,0,0.32))',
                  mt: 1.5,
                  '& .MuiAvatar-root': {
                    width: 32,
                    height: 32,
                    ml: -0.5,
                    mr: 1,
                  },
                  '&::before': {
                    content: '""',
                    display: 'block',
                    position: 'absolute',
                    top: 0,
                    right: 14,
                    width: 10,
                    height: 10,
                    bgcolor: 'background.paper',
                    transform: 'translateY(-50%) rotate(45deg)',
                    zIndex: 0,
                  },
                },
              }}
              transformOrigin={{ horizontal: 'right', vertical: 'top' }}
              anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
            >
              <MenuItem>
                <Avatar />
                <div className='flex !flex-col'>
                  <span className='text-[18px] font-[700]'>username</span>
                  <span className='text-[14px] font-[500] text-gray-500'>email</span>
                </div>
              </MenuItem>
              <hr />

              <MenuItem className='hover:!bg-[#ff5252] !text-[#fff]'>
                <Link to="/profile">
                  <ListItemIcon>
                    <AccountBoxOutlined fontSize="small" className='!text-[20px] !text-[#000000] !font-[700] hover:!text-[#fff]' />
                  </ListItemIcon>

                  <span className='text-[15px] text-gray-500 font-[700] hover:!text-[#fff]'>Profile</span>
                </Link>
              </MenuItem>

              <MenuItem
                className='hover:!bg-[#ff5252] !text-[#fff]'
               
              >
                <ListItemIcon>
                  <Logout fontSize="small" className='!text-[20px] !text-[#000000] hover:!text-[#fff] !font-[700]' />
                </ListItemIcon>
                <span className='text-[15px] text-gray-500 font-[700] hover:!text-[#fff]'>Sign Out</span>
              </MenuItem>
            </Menu>
       
        
          <Button
            className='btn-btn !bg-[#ff5252] !text-[#ffffff]'
            color='primary'
            
          >
            Sign in
          </Button>
      
      </div>
    </header>






   <Dialog
     fullScreen
  open={context.openFullscreemProduct.open}


  aria-hidden="true"
      >
        <AppBar   sx={{
    position: 'relative',
    backgroundColor: 'antiquewhite',
    color: 'black', 
    
  }}>
          <Toolbar>
            <IconButton
              edge="start"
              color="inherit"
             
             aria-label="close"
            >
              <CloseIcon />
            </IconButton>
          <Typography>hello</Typography>
        
          </Toolbar>
        </AppBar>
       {/* i am going to add form with add product */}
       
      </Dialog>


 </>
  );
}

export default Header;
